# Writes the hedra command files of the moon-lander's world: moon.txt (the little moon, origin at its
# centre: the game turns it), pad.txt (the landing pad), stars.txt, planet.txt and the small game
# parts flame.txt, dust.txt, debris.txt, flag.txt. Run from models/env: /usr/bin/python3 make_env.py.
# hedra: up Z, front -Y (the camera side); colours exact Nyx8 (sRGB 0..1 of the ramp steps).
import math, random

C = {"ink": "0.031 0.078 0.118", "navy": "0.059 0.165 0.247", "slate": "0.125 0.224 0.310",
     "dusk": "0.306 0.286 0.373", "mauve": "0.506 0.384 0.443", "rose": "0.600 0.459 0.467",
     "tan": "0.765 0.639 0.541", "cream": "0.965 0.839 0.741"}
def mat(name, col, emit=False):
    s = f"material new {name} --base-color {C[col]} --no-slot"
    return s + (f" --emission {C[col]}" if emit else "")
def orient(nx, ny, nz):
    """rotation (x y z degrees, extrinsic XYZ) taking +Z to the unit vector n"""
    th = math.degrees(math.acos(max(-1, min(1, nz))))
    ph = math.degrees(math.atan2(ny, nx))
    return f"0 {th:.2f} {ph:.2f}"

# ---- moon: a faceted ball 4 m in radius, only its front half (the camera never sees the back: the
# game turns it about the view axis). Crater rims (low tori) on its face, boulders round its rim (the
# silhouette), so the turn reads on the horizon.
R = 4.0
rnd = random.Random(7)
m = ["# The moon: a faceted ball 4 m in radius, origin at its centre (the game rolls it about the view",
     "# axis). Front half only. Crater rims on its face, boulders on its rim. Generated by make_env.py.",
     "new", mat("Rock", "dusk"), mat("Dust", "mauve"),
     f"add mesh ico-sphere --name Moon --subdivisions 3 --radius {R}",
     "material assign Rock", "active Moon", "mode edit",
     'select face where "normal.y > 0.35"', "delete only-faces",
     "select all", "randomize --amount 0.07 --seed 3", "mode object"]
names = []
for i in range(9):
    # crater rims on the face: directions within ~65 degrees of the view axis (-Y)
    while True:
        a = rnd.uniform(0, 2 * math.pi); t = rnd.uniform(0.25, 1.1)
        n = (math.sin(t) * math.cos(a), -math.cos(t), math.sin(t) * math.sin(a))
        if all(math.acos(max(-1, min(1, n[0]*o[0] + n[1]*o[1] + n[2]*o[2]))) > 0.5 for o in names): break
    names.append(n)
    rr = rnd.uniform(0.35, 0.75)
    p = [c * (R - 0.02) for c in n]
    m += [f"add mesh torus --name Crater{i} --major-segments 9 --minor-segments 4 --major-radius {rr:.2f} "
          f"--minor-radius {0.11 + rr * 0.12:.2f} --location {p[0]:.3f} {p[1]:.3f} {p[2]:.3f} --rotation {orient(*n)}",
          "scale 1 1 0.55", "material assign Dust"]
bl = []
for i in range(12):
    # boulders on the rim (the silhouette ring y = 0), every 30 degrees with a jitter
    a = math.radians(i * 30 + rnd.uniform(-9, 9))
    r = rnd.uniform(0.22, 0.42)
    x, z = (R + r * 0.3) * math.cos(a), (R + r * 0.3) * math.sin(a)
    m += [f"add mesh ico-sphere --name Boulder{i} --subdivisions 1 --radius {r:.2f} --location {x:.3f} {rnd.uniform(-0.3, 0.2):.3f} {z:.3f} --rotation {rnd.uniform(0, 90):.0f} {rnd.uniform(0, 90):.0f} {rnd.uniform(0, 90):.0f}",
          "scale 1.2 1 0.8", "material assign Rock"]
m += ["select all", "shade flat", "export moon.glb"]
open("moon.txt", "w").write("\n".join(m) + "\n")

# ---- stars: specks on a plane 10 m behind the play area (glTF z -10), one to two art pixels
rnd = random.Random(21)
s = ["# Star field: unlit specks 10 m behind the moon. Generated by make_env.py.", "new", mat("Star", "cream", True)]
sn = []
for i in range(75):
    x, z = rnd.uniform(-9.5, 9.5), rnd.uniform(-4.5, 7.0)
    size = 0.13 if rnd.random() < 0.2 else 0.085
    sn.append(f"S{i}")
    s.append(f"add mesh cube --name S{i} --size {size} --location {x:.3f} 10 {z:.3f}")
s += ["select " + " ".join(sn), "active S0", "join", "rename S0 Stars", "material assign Star", "export stars.glb"]
open("stars.txt", "w").write("\n".join(s) + "\n")

# ---- planet: a banded giant with a tilted ring, high on the left, 8 m behind
open("planet.txt", "w").write(f"""# A ringed planet in the sky: a faceted ball r 1.3 with a darker band, a thin tilted ring.
# Generated by make_env.py.
new
{mat("Planet", "rose")}
{mat("Band", "mauve")}
{mat("Ring", "tan")}
add mesh ico-sphere --name Planet --subdivisions 2 --radius 1.3 --location 0 0 0
material assign Planet
active Planet
mode edit
select face where "abs(pos.z - 0.25) < 0.28"
material assign Band
mode object
add mesh torus --name Ring --major-segments 16 --minor-segments 4 --major-radius 2.1 --minor-radius 0.16
scale 1 1 0.3
apply --scale
set rotation 12 -20 0
material assign Ring
select all
shade flat
export planet.glb
""")

# ---- pad: an octagonal deck 2.2 m across on four struts that reach into the ground, two lamps
open("pad.txt", "w").write(f"""# The landing pad: an octagonal deck 2.2 m across, its top 0.5 m up, a pale deck top with metal
# sides, four struts down into the ground (to -0.5), two unlit lamps at its ends. Origin on the ground
# under its centre. Generated by make_env.py.
new
{mat("Metal", "dusk")}
{mat("Deck", "rose")}
{mat("Stripe", "cream")}
{mat("Lamp", "cream", True)}
add mesh cylinder --name Deck --vertices 8 --radius 1.19 --depth 0.28 --location 0 0 0.36 --rotation 0 0 22.5
material assign Deck
add mesh cylinder --name Stripe --vertices 8 --radius 1.21 --depth 0.07 --location 0 0 0.33 --rotation 0 0 22.5
material assign Stripe
add mesh cube --name StrutA --size 1 --location -0.7 -0.45 0.0
scale 0.14 0.14 0.9
apply --scale
add mesh cube --name StrutB --size 1 --location 0.7 -0.45 0.0
scale 0.14 0.14 0.9
apply --scale
add mesh cube --name StrutC --size 1 --location -0.7 0.45 0.0
scale 0.14 0.14 0.9
apply --scale
add mesh cube --name StrutD --size 1 --location 0.7 0.45 0.0
scale 0.14 0.14 0.9
apply --scale
select StrutA StrutB StrutC StrutD
material assign Metal
add mesh cube --name LampA --size 0.17 --location -1.08 0 0.58
add mesh cube --name LampB --size 0.17 --location 1.08 0 0.58
select LampA LampB
material assign Lamp
select all
shade flat
export pad.glb
""")

# ---- flame: a cone pointing down from the nozzle (origin at its top: the nozzle's mouth)
open("flame.txt", "w").write(f"""# Thruster flame: a 6-sided cone 0.8 m long pointing down, a cream core in a tan sheath, origin
# at its top (the nozzle's mouth); the game stretches and flickers it. Generated by make_env.py.
new
{mat("Sheath", "tan", True)}
{mat("Core", "cream", True)}
add mesh cone --name Sheath --vertices 6 --radius1 0.05 --radius2 0.24 --depth 0.8 --location 0 0 -0.4
material assign Sheath
add mesh cone --name Core --vertices 6 --radius1 0.04 --radius2 0.15 --depth 0.5 --location 0 -0.1 -0.25
material assign Core
select all
shade flat
export flame.glb
""")

# ---- dust puff, debris chunk, flag
open("dust.txt", "w").write(f"""# A dust puff: a faceted ball 0.5 m across (the game grows and fades it). Generated by make_env.py.
new
{mat("Dust", "mauve")}
add mesh ico-sphere --name Puff --subdivisions 1 --radius 0.25
material assign Dust
shade flat
export dust.glb
""")
open("debris.txt", "w").write(f"""# A debris chunk: a turned box of foil 0.3 m (the game throws it). Generated by make_env.py.
new
{mat("Foil", "rose")}
add mesh cube --name Chunk --size 0.3 --rotation 20 30 10
material assign Foil
shade flat
export debris.glb
""")
open("flag.txt", "w").write(f"""# A flag planted at each landing: a pole 0.9 m and a cream pennant. Origin at the pole's foot.
# Generated by make_env.py.
new
{mat("Pole", "dusk")}
{mat("Cloth", "cream")}
add mesh cube --name Pole --size 1 --location 0 0 0.45
scale 0.08 0.08 0.9
apply --scale
material assign Pole
add mesh cube --name Cloth --size 1 --location 0.22 0 0.74
scale 0.4 0.06 0.26
apply --scale
material assign Cloth
select all
shade flat
export flag.glb
""")
